<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';
require_once __DIR__ . '/../modules/mailer.php';
require_login(); start_app_session();
$user=current_user();$error='';$inviteUrl='';$flash='';$canInvite=in_array((string)$user['role'],['owner','admin'],true);
if(empty($_SESSION['team_csrf']))$_SESSION['team_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['team_csrf'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_role(['owner','admin']);
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Atualize a página.');}
    $email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$role=(string)($_POST['role']??'viewer');
    if(!$email||!in_array($role,['admin','manager','viewer'],true))$error='Informe um e-mail válido e um papel permitido.';
    else{try{$token=issue_team_invitation(tenant_id(),(string)$email,$role,(string)$user['id']);$inviteUrl=app_public_url().'/accept-invitation.php?token='.rawurlencode($token);if(app_mail_is_configured()){$safeUrl=htmlspecialchars($inviteUrl,ENT_QUOTES,'UTF-8');$tenantName=htmlspecialchars((string)($user['tenant_name']??'seu espaço'),ENT_QUOTES,'UTF-8');$html=app_email_page('Convite para sua equipe','<p>Você foi convidado para acessar o espaço <b>'.$tenantName.'</b> no Vértice.</p><p><a href="'.$safeUrl.'" style="display:inline-block;background:#16845c;color:#fff;padding:12px 18px;border-radius:8px;text-decoration:none">Aceitar convite</a></p><p>O link expira em sete dias e pode ser usado uma vez.</p>');app_send_email((string)$email,'Convite para equipe — Vértice',$html,"Você foi convidado para acessar o espaço ".($user['tenant_name']??'Vértice').".\n\nAceite o convite usando este link: $inviteUrl\n\nO link expira em sete dias.");$flash='Convite enviado por e-mail. Você também pode copiar o link abaixo.';}else{$flash='Convite criado, mas o e-mail não está configurado. Copie o link e envie para a pessoa.';}}catch(DomainException $exception){$error=$exception->getMessage();}catch(Throwable $exception){$flash='O convite foi criado, mas o e-mail não foi enviado. Copie o link abaixo e confira a configuração SMTP.';error_log('[Vértice] Falha no envio de convite de equipe: '.$exception->getMessage());}}
}
$members=tenant_members();$invitations=tenant_invitations();
function te($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$roleNames=['owner'=>'Proprietário','admin'=>'Administrador','manager'=>'Gestor','viewer'=>'Leitura'];
?>
